 null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-axis()\r\n///\r\n@mixin margin-axis($horizontal: null, $vertical: null) {\r\n  @include margin-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-center {\r\n  @include margin($x: auto);\r\n}\r\n\r\n///\r\n/// @alias margin-center()\r\n///\r\n@mixin mx-auto {\r\n  @include margin-center;\r\n}\r\n\r\n@mixin margin-middle {\r\n  @include margin($y: auto);\r\n}\r\n\r\n///\r\n/// @alias margin-middle()\r\n///\r\n@mixin my-auto {\r\n  @include margin-middle;\r\n}\r\n\r\n@mixin margin-all($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n///\r\n/// @alias margin-all()\r\n///\r\n@mixin margin-square($margin) {\r\n  @include margin-all($margin);\r\n}\r\n\r\n@mixin margin-auto {\r\n  @include margin-all(auto);\r\n}\r\n\r\n///\r\n/// @alias margin-auto()\r\n///\r\n@mixin m-auto {\r\n  @include margin-auto;\r\n}\r\n\r\n@mixin margin-none {\r\n  @include margin-all(0);\r\n}\r\n\r\n///\r\n/// @alias margin-none()\r\n///\r\n@mixin m-none {\r\n  @include margin-none;\r\n}\r\n\r\n///\r\n/// @alias m-none()\r\n///\r\n@mixin m-0 {\r\n  @include m-none;\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-xy()\r\n///\r\n@mixin margin-axis($vertical: null, $horizontal: null) {\r\n  @include margin-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-x($x: null) {\r\n  @include margin($x: $x);\r\n}\r\n\r\n///\r\n/// @alias margin-x()\r\n///\r\n@mixin mx($x: null) {\r\n  @include margin-x($x: $x);\r\n}\r\n\r\n@mixin mx-none {\r\n  @include mx($x: 0);\r\n}\r\n\r\n///\r\n/// @alias mx-none()\r\n///\r\n@mixin mx-0 {\r\n  @include mx-none;\r\n}\r\n\r\n@mixin margin-y($y: null) {\r\n  @include margin($y: $y);\r\n}\r\n\r\n///\r\n/// @alias margin-y()\r\n///\r\n@mixin my($y: null) {\r\n  @include margin-y($y: $y);\r\n}\r\n\r\n@mixin my-none {\r\n  @include my($y: 0);\r\n}\r\n\r\n///\r\n/// @alias my-n