 null,\r\n  $b: null,\r\n  $l: null,\r\n) {\r\n  @include padding(\r\n    $all: $a,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $t,\r\n    $right: $r,\r\n    $bottom: $b,\r\n    $left: $l,\r\n  );\r\n}\r\n\r\n@mixin padding-xy($x: null, $y: null) {\r\n  @include padding($x: $x, $y: $y);\r\n}\r\n\r\n///\r\n/// @alias padding-xy()\r\n///\r\n@mixin padding-axis($horizontal: null, $vertical: null) {\r\n  @include padding-xy($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin padding-all($padding) {\r\n  @include padding($all: $padding);\r\n}\r\n\r\n///\r\n/// @alias padding-all()\r\n///\r\n@mixin padding-square($padding) {\r\n  @include padding-all($padding);\r\n}\r\n\r\n@mixin padding-none {\r\n  @include padding-all(0);\r\n}\r\n\r\n///\r\n/// @alias padding-none()\r\n///\r\n@mixin p-none {\r\n  @include padding-none;\r\n}\r\n\r\n///\r\n/// @alias p-none()\r\n///\r\n@mixin p-0 {\r\n  @include p-none;\r\n}\r\n\r\n@mixin padding-x($x: null) {\r\n  @include padding($x: $x);\r\n}\r\n\r\n///\r\n/// @alias padding-x()\r\n///\r\n@mixin px($x: null) {\r\n  @include padding-x($x);\r\n}\r\n\r\n@mixin px-none {\r\n  @include px(0);\r\n}\r\n\r\n///\r\n/// @alias px-none()\r\n///\r\n@mixin px-0 {\r\n  @include px-none;\r\n}\r\n\r\n@mixin padding-y($y: null) {\r\n  @include padding($y: $y);\r\n}\r\n\r\n///\r\n/// @alias padding-y()\r\n///\r\n@mixin py($y: null) {\r\n  @include padding-y($y);\r\n}\r\n\r\n@mixin py-none {\r\n  @include py(0);\r\n}\r\n\r\n///\r\n/// @alias py-none()\r\n///\r\n@mixin py-0 {\r\n  @include py-none;\r\n}\r\n\r\n@mixin padding-top($top: null) {\r\n  @include padding($top: $top);\r\n}\r\n\r\n///\r\n/// @alias padding-top()\r\n///\r\n@mixin pt($top: null) {\r\n  @include padding-top($top);\r\n}\r\n\r\n@mixin pt-none {\r\n  @include pt(0);\r\n}\r\n\r\n///\r\n/// @alias padding-top()\r\n///\r\n@mixin pt-0 {\r\n  @include pt-none;\r\n}\r\n\r\n@mixin padding-right($right: null) {\r\n  @include padding($right: $right);\r\n}\r\n\r\n///\r\n/// @alias padding-right()\