me='dark'] & {\r\n      color: color.alpha(color.tint(colors.$blue, 16%), 0.8);\r\n    }\r\n  }\r\n}\r\n\r\n.valueFieldContainer {\r\n  @include flex.row($justify: center);\r\n}\r\n\r\n.valueField {\r\n  &.disabled {\r\n    opacity: 1;\r\n  }\r\n\r\n  .light &.disabled {\r\n    color: colors.$black;\r\n  }\r\n\r\n  .dark &.disabled {\r\n    color: colors.$white;\r\n  }\r\n\r\n  // by defaults, applies -$padding-x and -$padding-y in ValueField's styles,\r\n  // so we reset the absolute positions to 0 with position.absolute-fill()\r\n  &::before {\r\n    @include position.abs-fill;\r\n  }\r\n}\r\n\r\n.valueFieldInput {\r\n  @include transition.apply(color, opacity);\r\n\r\n  .pristine &, .disabled & {\r\n    color: inherit;\r\n  }\r\n\r\n  &.warning {\r\n    color: colors.$orange;\r\n  }\r\n\r\n  .valueField:not(.disabled) &.dim:not(:active) {\r\n    opacity: 0.64;\r\n  }\r\n}\r\n\r\n.ivField {\r\n  max-width: 32px;\r\n}\r\n\r\n.evField {\r\n  max-width: 32px;\r\n}\r\n\r\n.statValue {\r\n  @include transition.apply(color, opacity);\r\n\r\n  &.positive {\r\n    color: colors.$green;\r\n  }\r\n\r\n  &.negative {\r\n    color: colors.$red;\r\n  }\r\n\r\n  &.finalStat {\r\n    font-size: 11px;\r\n  }\r\n\r\n  &.empty {\r\n    opacity: 0.32;\r\n    user-select: none;\r\n  }\r\n}\r\n\r\n.statModsTable {\r\n  display: grid;\r\n  grid-template-columns: min-content max-content;\r\n  grid-auto-rows: max-content;\r\n  column-gap: 6px;\r\n  row-gap: 2px;\r\n  align-items: center;\r\n  max-width: 200px;\r\n}\r\n\r\n.statModValue {\r\n  grid-area: span 1 / span 1;\r\n  align-self: center;\r\n  font-weight: 600;\r\n  font-size: 11px;\r\n  text-align: right;\r\n\r\n  .light & {\r\n    &.positive {\r\n      color: color.shade(colors.$green, 16%);\r\n    }\r\n\r\n    &.negative {\r\n      color: color.shade(colors.$red, 16%);\r\n    }\r\n  }\r\n}\r\n\r\n.statModLabel {\r\n  grid-area: span 1 / span 1;\r\n  align-self: center;\r\n  font-size: 10px;\r\n  opacity: 0.88;\r\n}\r\n\r\n.stageValue {\r\n  @include flex.row-center;\r\n}\r\n\r\n.boostButton {\r\n  @include spacing.margin-xy($x: 3px);\r\n\r\n  &.pristine {\r\n    color: inherit;\r\n\r\n    .boostButtonLabel {\r\n      color: inherit;\r\n    }\r\n  }\r\n\r\n  &.disabled {\r\n    opacity: 0.64;\r\n\r\n    &.empty {\r\n      opacity: 0.32;\r\n    }\r\n  }\r\n}\r\n\r\n.boostBaseStatButton {\r\n  @include spacing.m-0;\r\n  font-family: inherit;\r\n  font-weight: inherit;\r\n  font-size: inherit;\r\n  text-transform: inherit;\r\n\r\n  &.disabled {\r\n    opacity: 1;\r\n  }\r\n}\r\n\r\n.boostModButtonLabel {\r\n  .light & {\r\n    color: colors.$black;\r\n  }\r\n\r\n  .dark & {\r\n    color: colors.$white;\r\n  }\r\n}\r\n","////\r\n/// @group spacing\r\n/// @access public\r\n/// @author Keith Choison <keith@tize.io>\r\n/// @since 0.1.0\r\n////\r\n\r\n@use 'functions/list';\r\n\r\n@mixin -spacing(\r\n  $prop,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('margin' 'padding', $prop) {\r\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\r\n  }\r\n\r\n  @if $top and $right and $bottom and $left { // all directions specified\r\n    @if $right == $left {\r\n      @if $top == $bottom {\r\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\r\n          #{$prop}: $top;\r\n        } @else { // $top (== $bottom) != $right (== $left)\r\n          #{$prop}: $top $right;\r\n        }\r\n      } @else { // $top != $bottom, but $right == $left\r\n        #{$prop}: $top $right $bottom;\r\n      }\r\n    } @else { // $right != $left\r\n      #{$prop}: $top $right $bottom $left;\r\n    }\r\n  } @else { // not all directions specified\r\n    @if $top {\r\n      #{$prop}-top: $top;\r\n    }\r\n\r\n    @if $right {\r\n      #{$prop}-right: $right;\r\n    }\r\n\r\n    @if $bottom {\r\n      #{$prop}-bottom: $bottom;\r\n    }\r\n\r\n    @if $left {\r\n      #{$prop}-left: $left;\r\n    }\r\n  }\r\n}\r\n\r\n// margin