n  @include inset($bottom: $bottom);\r\n}\r\n\r\n@mixin bottom-none {\r\n  @include bottom(0);\r\n}\r\n\r\n///\r\n/// @alias bottom-none()\r\n///\r\n@mixin bottom-0 {\r\n  @include bottom-none;\r\n}\r\n\r\n@mixin left($left) {\r\n  @include inset($left: $left);\r\n}\r\n\r\n@mixin left-none {\r\n  @include left(0);\r\n}\r\n\r\n///\r\n/// @alias left-none()\r\n///\r\n@mixin left-0 {\r\n  @include left-none;\r\n}\r\n\r\n@mixin unset-all {\r\n  @include inset-all(unset);\r\n}\r\n\r\n// translate\r\n\r\n@mixin translate(\r\n  $x: null,\r\n  $y: null,\r\n) {\r\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\r\n    @if $x and $x != 0 and $y and $y != 0 {\r\n      transform: translate($x, $y);\r\n    } @else if $x and $x != 0 {\r\n      transform: translateX($x);\r\n    } @else if $y and $y != 0 {\r\n      transform: translateY($y);\r\n    }\r\n  }\r\n}\r\n\r\n///\r\n/// @access private\r\n///\r\n@mixin -position(\r\n  $position: relative,\r\n  $all: null,\r\n  $x: null,\r\n  $y: null,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('relative' 'absolute' 'fixed' 'sticky', $position) {\r\n    @error 'Invalid $position value passed to the -position() mixin: #{$position}';\r\n  }\r\n\r\n  position: $position;\r\n  @include inset(\r\n    $all: $all,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $top,\r\n    $right: $right,\r\n    $bottom: $bottom,\r\n    $left: $left,\r\n  );\r\n}\r\n\r\n// relative\r\n\r\n@mixin relative {\r\n  @include -position($position: relative);\r\n}\r\n\r\n///\r\n/// @alias relative()\r\n///\r\n@mixin rel {\r\n  @include relative;\r\n}\r\n\r\n// absolute\r\n\r\n@mixin absolute(\r\n  $all: null,\r\n  $x: null,\r\n  $y: null,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @include -position(\r\n    $position: absolute,\r\n    $all: $all,\r\n    $x: $x,\r\n    $y: $y,\r\n    $top: $top,\r\n    $right: $right,\r\n    $bottom: $bottom,\r\n   